import { GEOLOGY_FORMATIONS, geologyPoint, type GeologyFormation } from './geologyData';
import { hash01, sampleMainlandHeight } from './terrainData';
import { RECT_ROCK_PARTS, rectRockSizing } from './rectRockData';
import { rockScaleForDiameter } from './rockPackData';
import type { PropPlacement } from './worldPropsData';

export type GeologyComposition=Readonly<{
  formation:GeologyFormation;pieces:readonly PropPlacement[];
}>;

/** Assemble one global composition per landmark. No piece is generated by a chunk. */
export function composeGeology(f:GeologyFormation):GeologyComposition{
  const pieces:PropPlacement[]=[];
  const point=(along:number,across:number)=>geologyPoint(f,along,across);
  const random=(i:number,offset=0)=>hash01(i,f.seed,offset+f.seed);
  const push=(role:string,i:number,p:Omit<PropPlacement,'id'>):void=>{
    pieces.push({id:`geo:${f.id}:${role}:${i}`,...p});
  };
  const wallCount=f.kind==='coastalCliff'?9:7;
  const wallHalf=f.length*.37;
  for(let i=0;i<wallCount;i++){
    const along=-wallHalf+2*wallHalf*i/(wallCount-1)+(random(i,1)-.5)*3;
    const at=point(along,0),low=point(along,-21),high=point(along,24);
    const base=sampleMainlandHeight(low.x,low.z)-3.5;
    const crest=sampleMainlandHeight(high.x,high.z)+(random(i,2)-.5)*3;
    const scale=Math.max(28,(crest-base)/.86);
    push('wall',i,{kind:'acantilado2',x:at.x,y:base,z:at.z,scale,
      yaw:Math.atan2(f.axisX,f.axisZ)+(random(i,3)-.5)*.18,
      worldHeight:scale*.86,worldRadius:scale*.7,climbable:i>=2&&i<=wallCount-3});
  }
  for(let i=0;i<2;i++){
    const along=(i===0?-.27:.24)*f.length;
    const at=point(along,-17);
    const pieceIndex=i===0?0:3;
    const size=rectRockSizing(pieceIndex,.35+random(i,4)*.4,.3+random(i,5)*.5);
    push('column',i,{kind:'rocasRectangulares',x:at.x,
      y:sampleMainlandHeight(at.x,at.z)-2,z:at.z,scale:size.scaleXZ,
      scaleXZ:size.scaleXZ,scaleY:size.scaleY,yaw:random(i,6)*Math.PI*2,
      pieceIndex,diameterMeters:size.diameterMeters,worldHeight:size.heightMeters,
      worldRadius:size.broadphaseRadiusMeters,climbable:RECT_ROCK_PARTS[pieceIndex].canHaveClimbRoute});
  }
  for(let i=0;i<2;i++){
    const at=point((i===0?-.18:.16)*f.length,-27);
    const pieceIndex=i===0?5:8;
    const size=rectRockSizing(pieceIndex,.4+random(i,7)*.4,random(i,8));
    push('transition',i,{kind:'rocasRectangulares',x:at.x,
      y:sampleMainlandHeight(at.x,at.z)-1.1,z:at.z,scale:size.scaleXZ,
      scaleXZ:size.scaleXZ,scaleY:size.scaleY,yaw:random(i,9)*Math.PI*2,
      pieceIndex,diameterMeters:size.diameterMeters,worldHeight:size.heightMeters,
      worldRadius:size.broadphaseRadiusMeters,climbable:false});
  }
  for(let i=0;i<2;i++){
    const at=point((i===0?-.31:.3)*f.length,-18);
    const scale=20+random(i,17)*5;
    push('outcrop',i,{kind:'formacionRocosa',x:at.x,
      y:sampleMainlandHeight(at.x,at.z)-4,z:at.z,
      scale,yaw:random(i,18)*Math.PI*2,worldHeight:scale,
      worldRadius:scale*.5,climbable:i===0});
  }
  const terraces=f.kind==='plateau'?3:2;
  for(let i=0;i<terraces;i++){
    const along=(i-(terraces-1)/2)*31;
    const at=point(along,25+(i%2)*9);
    const scale=f.kind==='plateau'?43:38;
    push('terrace',i,{kind:'mesetaPasto',x:at.x,
      y:sampleMainlandHeight(at.x,at.z)+.28-scale*.45,z:at.z,
      scale,yaw:(random(i,10)-.5)*.26,worldHeight:scale*.45,worldRadius:scale*.72});
  }
  for(let i=0;i<2;i++){
    const at=point((i===0?-.2:.2)*f.length,-5);
    const scale=27+(random(i,11)-.5)*3;
    push('step',i,{kind:'escalonRocoso',x:at.x,
      y:sampleMainlandHeight(at.x,at.z)+1-scale*.45,z:at.z,
      scale,yaw:(random(i,12)-.5)*.35,worldHeight:scale*.45,worldRadius:scale*.72});
  }
  for(let i=0;i<4;i++){
    const at=point((i-1.5)*f.length*.2+(random(i,13)-.5)*7,-35-random(i,14)*7);
    const partIndex=[2,4,6,8][i],rockDiameter=3.2+random(i,15)*2.4;
    push('rubble',i,{kind:'packRocas',x:at.x,
      y:sampleMainlandHeight(at.x,at.z)-.4,z:at.z,
      scale:rockScaleForDiameter(partIndex,rockDiameter),yaw:random(i,16)*Math.PI*2,
      partIndex,rockDiameter,worldRadius:rockDiameter*.55,climbable:false});
  }
  return {formation:f,pieces};
}

export const GEOLOGY_COMPOSITIONS:readonly GeologyComposition[]=GEOLOGY_FORMATIONS.map(composeGeology);
